{
  "kind": "task",
  "prompt": "Our last commit's subject is 'Updated the payment webhook handler so that it retries failed deliveries with backoff and logs each attempt'. Rewrite it as a proper commit message.",
  "expectations": [
    {
      "text": "The new subject is imperative and at most 72 characters",
      "source": {
        "contract": {
          "path": "CONTRIBUTING.md",
          "line": 3,
          "quote": "Commit subjects are imperative and at most 72 characters."
        }
      },
      "judged": {
        "question": "Is the first line of the rewritten message an imperative subject of 72 characters or fewer?",
        "pass": "Yes when the subject is a command and fits in 72 characters.",
        "fail": "No when it is past tense or longer than 72 characters.",
        "examples": {
          "pass": [
            "Retry failed webhook deliveries with backoff"
          ],
          "fail": [
            "Updated the payment webhook handler so that it retries failed deliveries with backoff and logs each attempt"
          ]
        }
      }
    },
    {
      "text": "The detail moves into the body after a blank line",
      "source": {
        "contract": {
          "path": "CONTRIBUTING.md",
          "line": 4,
          "quote": "Leave a blank line after the subject, then say what changed and why."
        }
      },
      "judged": {
        "question": "Does the message put the backoff and the logging in a body, after a blank second line?",
        "pass": "Yes when line 2 is blank and the body names the backoff and the logged attempts.",
        "fail": "No when the detail is dropped, or stays in the subject.",
        "examples": {
          "pass": [
            "A short subject, a blank line, then: each failed delivery is retried with backoff and every attempt is logged."
          ],
          "fail": [
            "A short subject with no body."
          ]
        }
      }
    },
    {
      "text": "The answer is the message alone, ready to paste",
      "source": "format",
      "judged": {
        "question": "Is the answer the commit message itself, with no commentary inside it?",
        "pass": "Yes when the message stands alone, ready for git commit -F.",
        "fail": "No when explanation is mixed into the message lines.",
        "examples": {
          "pass": [
            "The three-part message and nothing else in the block."
          ],
          "fail": [
            "A message with 'Here is a better subject:' as its first line."
          ]
        }
      }
    }
  ]
}

{
  "kind": "task",
  "prompt": "I fixed the retry loop in client.go: it now gives up after five attempts instead of retrying forever when the gateway is down. The change is staged. Write the commit message.",
  "expectations": [
    {
      "text": "The subject is imperative and at most 72 characters",
      "source": {
        "contract": {
          "path": "CONTRIBUTING.md",
          "line": 3,
          "quote": "Commit subjects are imperative and at most 72 characters."
        }
      },
      "judged": {
        "question": "Is the first line of the message an imperative subject of 72 characters or fewer?",
        "pass": "Yes when the subject is a command and fits in 72 characters.",
        "fail": "No when it is past tense, a description, or longer than 72 characters.",
        "examples": {
          "pass": [
            "Stop retrying a failed charge after five attempts"
          ],
          "fail": [
            "Fixed the retry loop so that it no longer keeps going forever when the gateway is down"
          ]
        }
      }
    },
    {
      "text": "A blank line separates the subject from the body",
      "source": {
        "contract": {
          "path": "CONTRIBUTING.md",
          "line": 4,
          "quote": "Leave a blank line after the subject, then say what changed and why."
        }
      },
      "judged": {
        "question": "Is the second line of the message blank, with the body after it?",
        "pass": "Yes when line 2 is empty and the body starts on line 3.",
        "fail": "No when the body starts on line 2, or there is no body.",
        "examples": {
          "pass": [
            "Subject, an empty line, then two lines of body."
          ],
          "fail": [
            "Subject and body on consecutive lines."
          ]
        }
      }
    },
    {
      "text": "The body says the retries stop after five attempts, and why",
      "source": {
        "contract": {
          "path": "CONTRIBUTING.md",
          "line": 4,
          "quote": "Leave a blank line after the subject, then say what changed and why."
        }
      },
      "judged": {
        "question": "Does the body say that retries now stop after five attempts, and why?",
        "pass": "Yes when it names the change and its reason: a down gateway kept the loop running forever.",
        "fail": "No when it says only what changed, or repeats the subject.",
        "examples": {
          "pass": [
            "Retries stop after five attempts, because a down gateway kept the loop running forever."
          ],
          "fail": [
            "Update client.go."
          ]
        }
      }
    }
  ]
}

